from pathlib import Path
import html, shutil, sys

ROOT = Path(sys.argv[1]) if len(sys.argv)>1 else Path('/Users/gschiemann/.codex/worktrees/hospitality-guest-essentials/EDU CMS')
DEST = ROOT / 'scratch/design/guest-essentials'
DEST.mkdir(parents=True, exist_ok=True)
ASSETS = DEST / 'assets'
ASSETS.mkdir(exist_ok=True)
fonts = ROOT / 'apps/web/public/templates/signage/corporate/commercial-touch/assets'
for name in ['Newsreader', 'Manrope', 'Syne', 'SpaceMono']:
    shutil.copy2(fonts / (name + '.ttf'), ASSETS / (name + '.ttf'))
    shutil.copy2(fonts / (name + '-OFL.txt'), ASSETS / (name + '-OFL.txt'))
photos = ROOT / 'apps/web/public/templates/signage/hospitality/assets'
shutil.copy2(photos / 'hospitality-lobby-grand-room-v1.jpg', ASSETS / 'lobby.jpg')
shutil.copy2(photos / 'hospitality-lobby-goldenhour-pool-v1.jpg', ASSETS / 'pool.jpg')

def f(key, text, cls='', tag='div', floor=60):
    return f'<{tag} class="{cls}" data-field="{key}" data-fit data-fit-min="{floor}">{html.escape(text)}</{tag}>'

def photo(src, cls='photo'):
    return f'<div class="{cls} image-slot" data-imgslot="hero.photo" data-img="assets/{src}" role="img" aria-label="Hotel atmosphere"><div class="placeholder"></div></div>'

def logo():
    return '<div class="logo image-slot" data-imgslot="brand.logo" data-img="" aria-label="Hotel logo">'+f('brand.initial','A','logo-fallback')+'</div>'

def identity():
    return '<div class="identity">'+logo()+'<div>'+f('brand.name','THE ALDER','brand-name')+f('brand.descriptor','HOTEL & GARDEN','brand-descriptor',floor=50)+'</div></div>'

def info(key, label, value, detail, cls=''):
    return f'<section class="info {cls}" aria-label="{label}">'+f(key+'.label',label,'info-label',floor=50)+f(key+'.value',value,'info-value')+f(key+'.detail',detail,'info-detail')+'</section>'

def help_block():
    return '<div class="help-block">'+f('help.label','A LITTLE HELP','foot-label',floor=50)+f('help.value','Reception · dial 0','foot-value')+f('help.detail','Step-free entrance · East doors','foot-detail')+'</div>'

def shuttle():
    return '<div class="shuttle-block">'+f('shuttle.label','AIRPORT SHUTTLE','foot-label',floor=50)+f('shuttle.value','Every 30 min · 6 AM–10 PM','foot-value')+f('shuttle.detail','Meet at the main entrance · Book at reception','foot-detail')+'</div>'

